import java.net.*;
import java.io.*;
import org.json.*;
public class EnglishSpeakers {
    public static void main(String[] args) {
        try {
            // Set up the API endpoint URL
            String endpoint = "https://api.ethnologue.com/language/eng";
            // Send a GET request to the API endpoint
            URL url = new URL(endpoint);
            HttpURLConnection con = (HttpURLConnection) url.openConnection();
            con.setRequestMethod("GET");
            // Read the response from the API
            BufferedReader in = new BufferedReader(new InputStreamReader(con.getInputStream()));
            String inputLine;
            StringBuffer response = new StringBuffer();
            while ((inputLine = in.readLine()) != null) {
                response.append(inputLine);
            }
            in.close();
            // Parse the JSON response to extract the number of English speakers
            JSONObject obj = new JSONObject(response.toString());
            int numSpeakers = obj.getJSONObject("population").getInt("speakers");
            // Print the number of English speakers
            System.out.println("Estimated number of English speakers in the world: " + numSpeakers);
        } catch (Exception e) {
            System.out.println("Error: " + e.getMessage());
