```
package main
import (
	"fmt"
	"time"
	mqtt "github.com/eclipse/paho.mqtt.golang"
)
func main() {
	opts := mqtt.NewClientOptions().AddBroker("tcp://mqtt.eclipseprojects.io:1883")
	client := mqtt.NewClient(opts)
	if token := client.Connect(); token.Wait() && token.Error() != nil {
		panic(token.Error())
	}
	fmt.Println("Connected to MQTT broker")
	token := client.Subscribe("light-bulb", 0, func(client mqtt.Client, msg mqtt.Message) {
		fmt.Printf("Received message: %s from topic: %s\n", msg.Payload(), msg.Topic())
		// Turn on the light bulb here
	})
	token.Wait()
	if token.Error() != nil {
		panic(token.Error())
	}
	fmt.Println("Subscribed to topic: light-bulb")
	for {
		time.Sleep(1 * time.Second)
	}
}
```
This code connects to an MQTT broker, subscribes to the "light-bulb" topic, and turns on the light bulb when a message is received. Of course, the actual implementation of turning on the light bulb will depend on the specific device and protocol used.

