```swift
enum MassUnit {
    case kilograms
    case pounds

    func conversionFactor() -> Double {
        switch self {
        case .kilograms:
            return 1.0
        case .pounds:
            return 0.453592
        }
    }
}
enum DistanceUnit {
    case meters
    case feet

    func conversionFactor() -> Double {
        switch self {
        case .meters:
            return 1.0
        case .feet:
            return 0.3048
        }
    }
}
func calculateGravitationalForce(m1: Double, m2: Double, r: Double) -> Double {
    let G = 6.6743e-11 // gravitational constant
    let F = G * m1 * m2 / pow(r, 2) // gravitational force
    return F
}
func convertMass(mass: Double, fromUnit: MassUnit, toUnit: MassUnit) -> Double {
    let conversionFactor = fromUnit.conversionFactor() / toUnit.conversionFactor()
    return mass * conversionFactor
}
func convertDistance(distance: Double, fromUnit: DistanceUnit, toUnit: DistanceUnit) -> Double {
    let conversionFactor = fromUnit.conversionFactor() / toUnit.conversionFactor()
    return distance * conversionFactor
}
func calculateGravitationalForce(objects: [(mass: Double, distance: Double, massUnit: MassUnit, distanceUnit: DistanceUnit)]) -> Double {
    guard let firstObject = objects.first else { return 0 }
    let remainingObjects = Array(objects.dropFirst())
    let totalForce = remainingObjects.reduce(0) { (result, object) -> Double in
        let m1 = convertMass(mass: firstObject.mass, fromUnit: firstObject.massUnit, toUnit: object.massUnit)
        let m2 = convertMass(mass: object.mass, fromUnit: object.massUnit, toUnit: firstObject.massUnit)
        let r = convertDistance(distance: object.distance, fromUnit: object.distanceUnit, toUnit: firstObject.distanceUnit)
        let force = calculateGravitationalForce(m1: m1, m2: m2, r: r)
        let recursiveForce = calculateGravitationalForce(objects: [(mass: firstObject.mass, distance: object.distance, massUnit: firstObject.massUnit, distanceUnit: firstObject.distanceUnit)]) + calculateGravitationalForce(objects: [(mass: object.mass, distance: firstObject.distance, massUnit: object.massUnit, distanceUnit: object.distanceUnit)])
        return result + force + recursiveForce
    }
    return totalForce
}
```
