public double CalculateEmissions(double fuelEfficiency, double engineSize, double ageOfCar, double milesDriven)
{
    double emissions = 0;
    double co2PerGallon = 19.6; // pounds of CO2 emitted per gallon of gasoline
    double gallonsConsumed = milesDriven / fuelEfficiency;
    double co2Emissions = co2PerGallon * gallonsConsumed;

