  let solutionSet = [];
  let discriminant = b * b - 4 * a * c;
  if (discriminant < 0) {
    let realPart = -b / (2 * a);
    let imaginaryPart = Math.sqrt(-discriminant) / (2 * a);
    solutionSet.push(
      realPart.toFixed(2) + "+" + imaginaryPart.toFixed(2) + "i",
