using namespace std;
bool isDoubleEntendre(string joke) {
    // Check if the joke contains a double entendre
    return joke.find("horse") != string::npos || joke.find("duck") != string::npos;
}
bool isAnimalPunchline(string joke) {
    // Check if the joke has an animal punchline
    return joke.find("bear") != string::npos || joke.find("seagull") != string::npos || joke.find("penguin") != string::npos;
