int main() {
    vector<string> jokes = {"Why did the bear dissolve in water?",
                            "Why don't scientists trust atoms?",
                            "Why do seagulls fly over the sea?",
                            "How does a penguin build its house?",
                            "Why did the horse go to the doctor?",
                            "Why did the duck cross the road?"};
    vector<int> upvotes = {15, 27, 10, 35, 20, 30}; // Example upvote numbers
    vector<string> filteredJokes;
    for (string joke : jokes) {
        if (isDoubleEntendre(joke) && isAnimalPunchline(joke)) {
            filteredJokes.push_back(joke);
