```
package main
import (
    "database/sql"
    "fmt"
    _ "github.com/go-sql-driver/mysql"
)
func main() {
    db, err := sql.Open("mysql", "user:password@tcp(localhost:3306)/database")
    if err != nil {
        panic(err.Error())
    }
    defer db.Close()
    rows, err := db.Query("SELECT COUNT(*) FROM vehicles WHERE area = ? AND year >= ? AND year <= ? GROUP BY type", "metropolitan", 2010, 2021)
    if err != nil {
        panic(err.Error())
    }
    defer rows.Close()
    for rows.Next() {
        var count int
        err = rows.Scan(&count)
        if err != nil {
            panic(err.Error())
        }
        fmt.Printf("Total number of vehicles of this type: %d\n", count)
    }
}
```
